frontmatter.style:
section {
  font-size: 1.55rem;
  padding: 60px 70px;
  color: #1b2230;
}
section.lead {
  text-align: center;
  background: linear-gradient(135deg, #1b2838 0%, #2a3f5f 100%);
  color: #f5f5f7;
  justify-content: center;
}
section.lead h1 { font-size: 2.8rem; margin-bottom: 0.15em; color: #fff; }
section.lead h2 { font-size: 1.6rem; font-weight: 400; color: #cfd6e1; border: none; margin-top: 0; }
section.lead strong { color: #fff; }
section.lead em { color: #cfd6e1; }
section.refs { font-size: 1.1rem; }
section.refs ol { line-height: 1.4; padding-left: 1.2rem; }
h1, h2 { color: #1b2838; }
h2 { border-bottom: 2px solid #e3e6ed; padding-bottom: 0.2em; }
h3 { color: #2a3f5f; margin: 0.2em 0 0.25em 0; }
ul, ol { line-height: 1.4; }
.cols-2 {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 1.8rem;
  margin-top: 0.3rem;
}
.cols-3 {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 1.2rem;
  margin-top: 0.3rem;
}
.stat {
  text-align: center;
  padding: 0.9rem 0.5rem;
  background: #f4f4f7;
  border-radius: 8px;
}
.stat .big {
  display: block;
  font-size: 2.6rem;
  font-weight: 700;
  color: #1b2838;
  line-height: 1.05;
  margin-bottom: 0.2em;
}
.callout {
  background: #eef3fb;
  border-left: 5px solid #2a7ae2;
  padding: 0.7rem 1rem;
  margin-top: 0.9rem;
  border-radius: 4px;
}
.verdict {
  background: #fff5d6;
  border-left: 5px solid #d9a500;
  padding: 0.85rem 1.1rem;
  margin-top: 0.9rem;
  border-radius: 4px;
  font-size: 1.5rem;
}
table {
  font-size: 1.3rem;
  border-collapse: collapse;
  margin-top: 0.4rem;
}
table th, table td {
  padding: 0.35rem 0.8rem;
  border-bottom: 1px solid #d8dce3;
}
table th { background: #f4f4f7; text-align: left; }
blockquote {
  border-left: 5px solid #9aa4b2;
  color: #2a3f5f;
  margin: 0.8rem 0;
  padding-left: 1rem;
}
